Lemma rw_cells_CB1 : forall m A b cs, rw_cells asegs m A (CB 1 [b] :: cs) -> rw_cells asegs m A (C1 b :: cs).
Proof. intros m A b cs [[[_ W] B] R]. exact (conj (conj (conj I W) B) R). Qed.

